      const purchaseCatalogField=()=>`<label class="text-xs">Código MP o producto para reventa (vacío = gasto operativo)<select name="codigo" onchange="erpCatalogChanged(this)" class="mt-1 w-full p-2 border rounded"><option value="">Gasto operativo sin código</option>${mp.filter(x=>!x.archived).map(x=>`<option value="${esc(x.codigo)}">${esc(x.codigo)} · ${esc(x.detalle)} · MP</option>`).join('')}${nofab.filter(x=>!x.archived).map(x=>`<option value="${esc(x.codigo)}">${esc(x.codigo)} · ${esc(x.detalle)} · reventa</option>`).join('')}</select></label>`;
      window.erpCatalogChanged=control=>{
        const form=control.form;if(!form)return;const code=form.elements.namedItem('codigo')?.value||'',item=product(code)||mpItem(code),submit=form.getAttribute('onsubmit')||'',detail=form.elements.namedItem('detalle'),price=form.elements.namedItem('precio');
        if(submit.startsWith('erpGasto')){
          const value=form.elements.namedItem('valor'),quantity=form.elements.namedItem('cantidad'),unitCost=item?(mpItem(code)?num(item.precio):num(item.costo)):0;
          if(detail&&(!detail.value||detail.dataset.catalogValue===detail.value)){detail.value=item?.detalle||'';detail.dataset.catalogValue=detail.value;}
          if(value&&(!value.value||value.value==='0'||value.dataset.catalogAuto==='1')){value.value=(Math.max(0,num(quantity?.value))*unitCost).toFixed(2);value.dataset.catalogAuto='1';}
          return;
        }
        if(detail&&(!detail.value||detail.dataset.catalogValue===detail.value)){detail.value=item?.detalle||'';detail.dataset.catalogValue=detail.value;}
        if(!price)return;
        if(submit.startsWith('erpVenta')||submit.startsWith('erpCredito'))price.value=item?num(item.publico):'';
        else if(submit.startsWith('erpConsigna'))price.value=item?num(item.mayorista):'';
        else if(submit.startsWith('erpEntrada')){const type=form.elements.namedItem('tipo');if(type&&item)type.value=item.tipoCatalogo==='Reventa'||nofab.includes(item)?'reventa':'fabricado';if(price){const resale=type?.value==='reventa';price.required=resale;price.min=resale?'0.01':'0';price.value=item?(resale?num(item.costo):0):'';}}
      };
      window.erpPurchaseRecalculate=form=>{
        const code=form?.elements.namedItem('codigo')?.value||'',item=mpItem(code)||nofab.find(p=>p.codigo===code&&!p.archived),value=form?.elements.namedItem('valor'),quantity=form?.elements.namedItem('cantidad');
        if(value&&value.dataset.catalogAuto==='1')value.value=(Math.max(0,num(quantity?.value))*(item?(mpItem(code)?num(item.precio):num(item.costo)):0)).toFixed(2);
      };
      function renderMobileDashboard(){const meta={productos:['PT','Productos terminados y stock'],materias:['MP','Catálogo de materias primas'],produccion:['+','Entradas y producción'],ventas:['V','Registrar y consultar ventas'],gastos:['−','Gastos y compras'],plan:['C','Costos y fabricación'],creditos:['$','Créditos, abonos y devoluciones'],clientes:['CL','Directorio y saldos de clientes'],nofab:['NP','Costos no producidos'],consignacion:['CO','Entregas y liquidaciones'],balance:['B','Cierre y balance mensual']};return `<section class="dashboard-home space-y-4"><header class="dashboard-welcome rounded-2xl bg-gradient-to-r from-indigo-950 to-indigo-700 p-4 text-white"><p class="text-[10px] font-black uppercase tracking-[.18em] text-indigo-200">COLIPETS · INICIO</p><h2 class="mt-1 text-xl font-black">Módulos de trabajo</h2><p class="mt-1 text-xs text-indigo-100">Selecciona una sección para comenzar.</p></header><div id="dashboardModuleGrid" aria-label="Módulos COLIPETS">${nav.map(([id,title])=>{const [badge,desc]=meta[id]||['•',title];return `<button type="button" onclick="erpView('${id}')" class="dashboard-module-card flex w-full items-center gap-3 rounded-xl border border-slate-200 bg-white p-3 text-left shadow-sm"><span class="dashboard-module-icon grid h-10 w-10 shrink-0 place-items-center rounded-lg bg-indigo-100 text-sm font-black text-indigo-900">${badge}</span><span class="min-w-0 flex-1"><strong class="block text-xs font-black text-slate-900">${title}</strong><small class="mt-1 block text-[11px] text-slate-500">${desc}</small></span><span class="dashboard-module-arrow text-lg font-bold text-indigo-700">→</span></button>`}).join('')}</div><p class="dashboard-data-note text-center text-[10px] text-slate-500">Los registros se guardan en este dispositivo.</p></section>`;}
      function renderGuide(){return `<div class="erp-guide"><div class="erp-guide-hero"><p>MANUAL R&Aacute;PIDO</p><h2>C&oacute;mo registrar en COLIPETS</h2><p>Siga el orden de cada proceso. El cat&aacute;logo crea referencias; solo los movimientos confirmados afectan existencias o caja.</p></div><div class="erp-guide-grid">${[
['1 &middot; Materias primas','Primero cree cada insumo en Materias primas: c&oacute;digo &uacute;nico, nombre, costo unitario, unidad y dimensiones de compra. Este cat&aacute;logo alimenta la calculadora, el plan de corte y las compras. Corrija unidad y dimensiones antes de fabricar.'],
['2 &middot; Ficha de producto fabricado','Abra Calculadora de costos, escriba el c&oacute;digo y detalle del producto, asigne materiales y cantidades, revise mano de obra y componentes, y use Guardar en productos terminados. Esto guarda la ficha y sus costos; no crea existencias.'],
['3 &middot; Producto de reventa','Abra No fabricados y registre c&oacute;digo, detalle, costo directo y minutos si aplican. El art&iacute;culo queda disponible para compras, ventas y cotizaciones. No usa el desperdicio de fabricaci&oacute;n.'],
['4 &middot; Plan de fabricaci&oacute;n','El c&oacute;digo debe existir primero como producto fabricado: gu&aacute;rdelo con la calculadora. Despu&eacute;s, en Plan de fabricaci&oacute;n, seleccione el c&oacute;digo y complete medidas y unidades. El plan solo calcula; no consume materiales. Si faltan costos o medidas, revise la ficha o el cat&aacute;logo MP.'],
['5 &middot; Compra y recepci&oacute;n','En Gastos y compras, escriba un c&oacute;digo MP v&aacute;lido para comprar material; para reventa use el c&oacute;digo de un producto no fabricado. Indique cantidad, valor total y pago de hoy. El inventario sube por la cantidad recibida; caja baja solo por el pago. C&oacute;digo vac&iacute;o significa gasto operativo; c&oacute;digo inv&aacute;lido se rechaza.'],
['6 &middot; Confirmar producci&oacute;n','Antes de producir: ficha guardada, c&oacute;digo existente, ficha t&eacute;cnica completa y stock MP suficiente. En Producci&oacute;n / entradas indique c&oacute;digo y unidades enteras. Confirmar descuenta consumos una vez y registra la entrada PT ligada a la orden. Una compra para reventa no consume MP.'],
['7 &middot; Clientes, ventas y cr&eacute;ditos','Registre o seleccione un cliente. En Ventas use existencia disponible y confirme precio, descuento total y medio de pago. Para fiar use Cr&eacute;ditos y abonos: el cr&eacute;dito descuenta stock y crea saldo, el abono no descuenta productos. La cantidad debe ser positiva y el descuento no puede superar el subtotal.'],
['8 &middot; Consignaci&oacute;n y devoluci&oacute;n','Entregue solo unidades disponibles; quedan comprometidas, no cobradas. Use Liquidar y cobrar cuando reciba el pago. Si la mercanc&iacute;a vuelve f&iacute;sicamente, registre Devolver recibida. Una devoluci&oacute;n de venta se vincula al movimiento original y solo reintegra stock si se recibe la mercanc&iacute;a.'],
['9 &middot; Cotizaciones','Seleccione hasta diez referencias activas y cantidades. Para medidas especiales use un producto fabricado, ancho/largo y margen. La cotizaci&oacute;n puede imprimirse y no cambia stock, gastos ni caja.'],
['10 &middot; Informes y respaldo','Balance, flujo y resultado se revisan por mes/a&ntilde;o con el detalle de movimientos. Las fechas determinan el periodo; las compras de inventario no son gasto operativo por defecto. Exporte JSON en Copias de seguridad con frecuencia y antes de cambiar de equipo.']
].map(([title,body])=>`<article class="erp-guide-card"><h3>${title}</h3><p>${body}</p></article>`).join('')}</div><div class="erp-guide-warning"><h3>&iquest;Me equivoqu&eacute;? C&oacute;mo corregirlo</h3><ul><li>En una fila de operaci&oacute;n use <b>Anular</b>. El sistema conserva el original y registra la reversi&oacute;n.</li><li>En Productos terminados, No fabricados o Materias primas use <b>Eliminar / retirar</b>. Si no hay movimientos vinculados, se elimina del cat&aacute;logo. Si ya existe historial, se archiva y deja de ofrecerse en operaciones nuevas.</li><li>Un cat&aacute;logo archivado se puede restaurar desde el mismo listado. Si el error est&aacute; en una operaci&oacute;n confirmada, anule esa operaci&oacute;n y registre el movimiento correcto.</li><li>Una cotizaci&oacute;n se puede anular desde su fila; no afecta inventario ni caja. Una ficha se corrige en la calculadora y se vuelve a guardar.</li></ul><p>El sistema pide confirmaci&oacute;n antes de retirar o anular. Los registros relacionados no se borran en silencio.</p></div></div>`;}
      function injectCatalogHints(viewId){
        let candidates=(viewId==='cotizar'?pt.concat(designs,nofab):pt.concat(nofab)).filter(p=>!p.archived);
        if(viewId==='gastos') candidates=candidates.concat(mp.filter(m=>!m.archived));
        const inputs=[...ws.querySelectorAll('input[name="codigo"],input[name^="c"]')].filter(x=>x.name==='codigo'||/^c(?:[1-9]|10)$/.test(x.name));
        inputs.forEach((input,index)=>{
          const specialQuote=viewId==='cotizar'&&input.form?.getAttribute('onsubmit')?.includes('erpCotizacionEspecial'),specialCandidates=[...new Map([...designs,...pt].map(p=>[p.codigo,p])).values()].filter(p=>{const d=quoteBaseDimensions(p.codigo,p);return !p.archived&&num(p.costo)>0&&d.width>0&&d.length>0;}),rows=viewId==='materias'?mp.filter(m=>!m.archived):specialQuote?specialCandidates:candidates,dl=document.createElement('datalist'),id=`colipets-options-${viewId}-${index}`;dl.id=id;
          dl.innerHTML=rows.map(x=>{const baseHint=specialQuote?quoteBaseDimensions(x.codigo,x):null;return `<option value="${esc(x.codigo)}">${esc(x.codigo)} - ${esc(x.detalle||'Sin detalle')}${baseHint?` (base ${baseHint.width} x ${baseHint.length} cm)`:''}</option>`}).join('');input.setAttribute('list',id);
          const info=document.createElement('div');info.className='mt-1 rounded-lg border border-indigo-100 bg-indigo-50 px-2 py-1 text-[11px] text-indigo-900';info.dataset.catalogInfo='1';info.setAttribute('aria-live','polite');input.insertAdjacentElement('afterend',dl);dl.insertAdjacentElement('afterend',info);
          const apply=()=>{const code=input.value.trim().toUpperCase();let item=(viewId==='materias'?mp:candidates).find(x=>!x.archived&&String(x.codigo).trim().toUpperCase()===code);if(!item){info.textContent=code?'C\u00f3digo no encontrado en el cat\u00e1logo. Revise la referencia.':'Seleccione o escriba un c&oacute;digo del cat\u00e1logo.';info.className='mt-1 rounded-lg border border-amber-200 bg-amber-50 px-2 py-1 text-[11px] text-amber-900';return;}
            info.textContent=`${item.codigo} \u00b7 ${item.detalle||'Sin detalle registrado'}${Number.isFinite(Number(item.costo??item.precio))?` \u00b7 Costo ${money(item.costo??item.precio)}`:''}${Number.isFinite(Number(item.publico))?` \u00b7 P\u00fablico ${money(item.publico)}`:''}`;info.className='mt-1 rounded-lg border border-emerald-200 bg-emerald-50 px-2 py-1 text-[11px] text-emerald-900';
            if(viewId==='materias'){const f=input.form;if(f){for(const [name,value] of Object.entries({detalle:item.detalle||'',precio:item.precio??0,largo:item.largo??0,ancho:item.ancho??0,unidad:({'Metros':'m','Metro':'m','Kilos':'kg','Kilo':'kg','Gramos':'g','Gramo':'g','Centimetros':'cm','Cent&iacute;metros':'cm','Unidad':'unidad'}[item.unidad]||item.unidad||'unidad'),contenidoUnidad:item.contenidoUnidad||1,cantidadInicial:0})){const el=f.elements.namedItem(name);if(el&&name!=='cantidadInicial')el.value=value;}}}
            else {const f=input.form,detail=f?.elements.namedItem('detalle'),price=f?.elements.namedItem('precio');if(detail&&viewId!=='gastos')detail.value=item.detalle||'';if(price&&['ventas','creditos','consignacion'].includes(viewId))price.value=String(viewId==='consignacion'?num(item.mayorista):num(item.publico));}
          };
          input.addEventListener('change',apply);input.addEventListener('input',apply);
          if(viewId==='cotizar'&&input.value)apply();
        });
      }
      function injectRowActions(viewId){
        const table=ws.querySelector('table');
        const addHeader=t=>{const h=t?.tHead?.rows?.[0];if(h&&!h.dataset.actionColumn){const th=document.createElement('th');th.textContent='Acciones';th.className='text-right';h.appendChild(th);h.dataset.actionColumn='1';}};
        const btn=(label,handler,kind='danger')=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.className=`rounded-lg border px-2 py-1 text-xs font-bold ${kind==='restore'?'border-emerald-300 bg-emerald-50 text-emerald-800':'border-rose-300 bg-rose-50 text-rose-800'} hover:brightness-95`;b.onclick=handler;return b;};
        const catalog=viewId==='materias'?mp:viewId==='nofab'?nofab:viewId==='productos'?pt.concat(nofab):null;
        if(catalog&&table){addHeader(table);[...table.tBodies[0]?.rows||[]].forEach((tr,i)=>{const x=catalog[i];if(!x)return;const td=document.createElement('td');td.className='text-right whitespace-nowrap';if(viewId==='materias'&&!x.archived)td.appendChild(btn('Editar',()=>window.erpEditMaterial(x.codigo),'restore'));td.appendChild(btn(x.archived?'Restaurar':'Eliminar / retirar',()=>window.erpDeleteCatalog(viewId==='materias'?'mp':(viewId==='nofab'||nofab.includes(x))?'nofab':'pt',x.codigo),x.archived?'restore':'danger'));tr.appendChild(td);if(x.archived)tr.classList.add('opacity-60');});}
        if(viewId==='consignacion'&&table){const items=mov.filter(m=>m.type==='consignacion_entrega');addHeader(table);[...table.tBodies[0]?.rows||[]].forEach((tr,i)=>{const m=items[i];if(!m)return;const td=document.createElement('td');td.appendChild(m.void?document.createTextNode('Anulada'):btn('Anular entrega',()=>window.erpVoid(m.id)));tr.appendChild(td);});}
        if(viewId==='recursos'&&table){const items=mov.filter(m=>['manoObraIndirecta','manoObraDirectaPago','activoFijo','reservaActivo','otherIngreso'].includes(m.type));addHeader(table);[...table.tBodies[0]?.rows||[]].forEach((tr,i)=>{const m=items[i];if(!m)return;const td=document.createElement('td');td.appendChild(m.void?document.createTextNode('Anulado'):btn('Anular',()=>window.erpVoid(m.id)));tr.appendChild(td);});}
        if(viewId==='cotizar'&&table){addHeader(table);[...table.tBodies[0]?.rows||[]].forEach((tr,i)=>{const q=quotes[i];if(!q)return;const td=document.createElement('td');td.className='whitespace-nowrap';td.appendChild(btn('Ver / imprimir',()=>window.erpShowQuote(q),'restore'));if(!q.cancelled)td.appendChild(btn('Anular',()=>window.erpCancelQuote(q.operationId||q.numero)));else td.appendChild(document.createTextNode(' Anulada'));tr.appendChild(td);if(q.cancelled)tr.classList.add('opacity-60');});}
      }
      function configureModuleForms(viewId){
        const required={
          erpSaveMP:['codigo','detalle','precio'],erpSaveNofab:['codigo','detalle','directo'],
          erpEntrada:['codigo','cantidad','tipo','fecha'],erpVenta:['cliente','codigo','cantidad','precio','medio','fecha'],
          erpCredito:['cliente','codigo','cantidad','precio','fecha'],erpAbono:['cliente','valor','medio','fecha'],
          erpDevolucion:['ref','reintegro','fecha'],erpGasto:['detalle','valor','fecha'],
          erpConsigna:['factura','cliente','codigo','cantidad','precio','fecha'],erpConsignaAccion:['ref','accion','fecha'],
          erpCliente:['nombre'],erpLabor:['valor','fecha'],erpAsset:['detalle','valor','vida','fecha'],
          erpPayable:['ref','valor','fecha'],erpOtherIncome:['detalle','valor','fecha'],erpReserve:['valor','fecha']
        };
        for(const form of ws.querySelectorAll('form[onsubmit]')){
          const submit=(form.getAttribute('onsubmit')||'').match(/^([A-Za-z0-9_]+)\(/)?.[1];
          for(const name of required[submit]||[]){const control=form.elements.namedItem(name);if(control)control.required=true;}
          if(['erpEntrada','erpVenta','erpCredito','erpConsigna','erpDevolucion'].includes(submit)){const quantity=form.elements.namedItem('cantidad');if(quantity)quantity.step='1';}
          const placeholders={erpEntrada:{tipo:'Seleccione el tipo'},erpVenta:{medio:'Seleccione el medio de pago'},erpAbono:{medio:'Seleccione el medio de pago'},erpDevolucion:{reintegro:'Confirme si vuelve físicamente'},erpConsignaAccion:{accion:'Seleccione una acción'},erpLabor:{clase:'Seleccione la clase'},erpGasto:{categoria:'Seleccione una categoría'}};
          for(const [name,label] of Object.entries(placeholders[submit]||{})){
            const control=form.elements.namedItem(name);
            if(control instanceof HTMLSelectElement&&!Array.from(control.options).some(option=>option.value==='')){control.insertBefore(new Option(label,''),control.firstChild);control.value='';}
          }
          if(submit==='erpEntrada'){
            const type=form.elements.namedItem('tipo');
            type?.addEventListener('change',()=>window.erpCatalogChanged(type));
          }
          if(submit==='erpGasto'){
            const code=form.elements.namedItem('codigo'),label=code?.closest('label'),quantity=form.elements.namedItem('cantidad'),value=form.elements.namedItem('valor'),category=form.elements.namedItem('categoria'),detail=form.elements.namedItem('detalle');
            if(code&&label){
              label.textContent='Código MP o producto para reventa (vacío = gasto operativo)';
              const selector=document.createElement('select');selector.name='codigo';selector.className='mt-1 w-full rounded border p-2';selector.innerHTML='<option value="">Gasto operativo sin código</option>'+mp.filter(x=>!x.archived).map(x=>`<option value="${esc(x.codigo)}">${esc(x.codigo)} · ${esc(x.detalle)} · MP</option>`).join('')+nofab.filter(x=>!x.archived).map(x=>`<option value="${esc(x.codigo)}">${esc(x.codigo)} · ${esc(x.detalle)} · reventa</option>`).join('');
              selector.addEventListener('change',()=>{const hasCode=Boolean(selector.value);quantity.required=hasCode;category.required=!hasCode;if(!hasCode&&value.dataset.catalogAuto==='1'){value.value='';value.dataset.catalogAuto='0';}window.erpCatalogChanged(selector);});
              label.append(selector);
            }
            if(quantity){quantity.min='0.01';if(num(quantity.value)<=0)quantity.value='1';quantity.addEventListener('input',()=>window.erpPurchaseRecalculate(form));}
            if(value){value.min='0.01';value.required=true;value.addEventListener('input',()=>{value.dataset.catalogAuto='0';});}
            if(detail)detail.required=true;
            if(category)category.required=true;
          }
          if(submit==='erpSaveMP'){
            const unit=form.elements.namedItem('unidad');if(unit)unit.required=true;
          }
          if(submit==='erpLabor'){
            const value=form.elements.namedItem('valor');if(value)value.min='0.01';
          }
        }
        for(const selector of ws.querySelectorAll('select[data-stock-filter="1"]')){
          const form=selector.form,dateControl=form?.elements.namedItem('fecha'),label=selector.closest('label');
          const refresh=()=>{
            const selected=selector.value,date=dateControl?.value||defaultMovementDate(),items=[...pt,...nofab].filter(p=>!p.archived&&productStockAt(p.codigo,date)-consAt(p.codigo,date)>0);
            selector.replaceChildren(new Option('Seleccione un producto',''));
            for(const item of items){const available=productStockAt(item.codigo,date)-consAt(item.codigo,date);selector.add(new Option(`${item.codigo} · ${item.detalle} · disponible ${available}`,item.codigo));}
            selector.value=items.some(p=>p.codigo===selected)?selected:'';
            let note=label?.querySelector('[data-stock-note]');
            if(!items.length){if(!note){note=document.createElement('small');note.dataset.stockNote='1';note.className='mt-1 block text-amber-800';label?.append(note);}if(note)note.textContent='No hay stock para la fecha seleccionada. Registre una entrada o realice un conteo físico antes de vender, otorgar crédito o consignar.';}
            else note?.remove();
            window.erpCatalogChanged(selector);
          };
          refresh();dateControl?.addEventListener('change',refresh);
        }
      }

      const select=(label,name,options,extra='')=>`<label class="text-xs">${label}<select name="${name}" ${extra} class="mt-1 w-full p-2 border rounded">${options.map(o=>`<option value="${esc(o[0])}">${esc(o[1])}</option>`).join('')}</select></label>`;
      const form=(title,fields,submit)=>`<section class="erp-new-record mb-4 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm"><button type="button" aria-expanded="false" onclick="const p=this.nextElementSibling;p.classList.toggle('hidden');this.setAttribute('aria-expanded',String(!p.classList.contains('hidden')))" class="flex w-full items-center justify-between gap-3 px-4 py-3 text-left text-sm font-bold text-indigo-950"><span>＋ Nuevo registro</span><small class="font-medium text-slate-500">${title}</small></button><div class="erp-form-panel hidden border-t bg-slate-50 p-4"><form onsubmit="${submit}(event)" data-operation-id="${uid()}" class="space-y-3"><h3 class="font-bold">${title}</h3><div class="grid grid-cols-2 md:grid-cols-4 gap-3">${fields}${['erpEntrada','erpVenta','erpCredito','erpAbono','erpDevolucion','erpGasto','erpConsigna','erpConsignaAccion','erpAsset','erpLabor','erpPayable','erpOtherIncome','erpReserve'].includes(submit)?field('Fecha del movimiento/pago','fecha','date'):''}</div><button class="px-4 py-2 bg-indigo-600 text-white rounded font-bold text-sm">Guardar registro</button></form></div></section>`;
