        if(migrationIssues.length&&id!=='revision'&&id!=='backup')content=`<div class="erp-review-banner"><b>${migrationIssues.length} datos por conciliar.</b> Hay códigos con costo/stock o fecha pendiente. <button class="underline font-bold ml-2" onclick="erpView('revision')">Revisar importación Excel</button></div>`+content;
        ws.innerHTML=content;
