      function renderQuoteForm(){return `<div class="flex items-center gap-3 rounded-xl border border-orange-200 bg-orange-50 p-3"><img src="${document.getElementById('colipetsFavicon')?.href||''}" alt="Logo COLIPETS" class="h-12 w-12 rounded-lg object-contain"><h2 class="text-2xl font-black text-indigo-950">COLIPETS - Cotizaciones</h2></div><section class="erp-section-card my-4"><h3 class="font-black text-indigo-900">Cotizaci&oacute;n general (hasta 10 referencias)</h3><p class="text-sm text-slate-600">Incluye fabricados y productos de reventa. La cotizaci&oacute;n no reserva ni descuenta existencias; se pueden cotizar art&iacute;culos sin stock.</p>${form('Datos y productos',clienteField()+field('Fecha de cotizacion','fecha','date')+field('Vigencia (dias)','vigencia','number','min="1" value="15"')+field('Margen comercial (%)','margen','number','min="0" value="30"')+Array.from({length:10},(_,i)=>field(`Linea ${i+1} - codigo`,'c'+(i+1))+field('Cantidad','q'+(i+1),'number','min="0" value="0"')).join(''),'erpCotizar')}</section><section class="erp-section-card my-4"><h3 class="font-black text-indigo-900">Cotizacion con medidas especiales</h3><p class="text-sm">Seleccione una referencia fabricada con medidas terminadas base y escriba las dimensiones solicitadas, aunque sean distintas a la base (por ejemplo, una cama 50 ? 50 puede cotizarse en 50 ? 55). Precio = costo base ? (&aacute;rea solicitada / &aacute;rea base) ? (1 + margen). Se usa la medida del nombre del producto cuando est&aacute; indicada; la ficha t&eacute;cnica se usa como respaldo. No requiere stock disponible.</p>${form('Producto base y medidas',clienteField()+field('Fecha de cotizacion','fecha','date')+field('C&oacute;digo del producto fabricado','codigo')+field('Cantidad','cantidad','number','min="1" value="1"')+field('Ancho nuevo solicitado (cm)','ancho','number','min="0.01" required')+field('Largo nuevo solicitado (cm)','largo','number','min="0.01" required')+field('Margen comercial (%)','margen','number','min="0" value="30"')+field('Vigencia (dias)','vigencia','number','min="1" value="15"'),'erpCotizacionEspecial')}</section><div id="cotOut"></div>${table(['Fecha','Vence','N.','Cliente','Total','Modalidad'],quotes.map(q=>`<tr><td>${esc(q.fecha)}</td><td>${esc(q.vence)}</td><td>${esc(q.numero)}</td><td>${esc(q.cliente)}</td><td>${money(q.total)}</td><td>${q.specialMeasure?'Medidas especiales':'General'}</td></tr>`).join(''))}`;}
      function showQuote(quote){const lines=quote.lines||[];document.getElementById('cotOut').innerHTML=`<div id="quotePrintArea" class="erp-section-card mt-4"><div class="flex items-center gap-3 border-b border-indigo-100 pb-3 mb-3"><img src="${document.getElementById('colipetsFavicon')?.href||''}" alt="Logo oficial COLIPETS" class="h-16 w-16 rounded-lg object-contain"><h3 class="font-black text-indigo-950">COLIPETS - Cotizacion ${esc(quote.numero)}</h3></div><p>Cliente: ${esc(quote.cliente||'')} &middot; Fecha: ${esc(quote.fecha)} &middot; V&aacute;lida hasta: ${esc(quote.vence)}</p>${quote.specialMeasure?`<p class="erp-review-badge">Modalidad especial - factor de area ${Number(quote.specialMeasure.factor).toFixed(4)}</p>`:''}${table(['Codigo','Descripcion','Cantidad','Precio unitario','Total'],lines.map(l=>`<tr><td>${esc(l.code)}</td><td>${esc(l.detalle)}</td><td>${l.q}</td><td>${money(l.unit)}</td><td>${money(l.total)}</td></tr>`).join(''))}<details class="internal-quote"><summary>Detalle interno de costos y utilidad</summary>${table(['Codigo','Costo unitario estimado','Precio unitario','Utilidad unitaria','Utilidad linea'],lines.map(l=>`<tr><td>${esc(l.code)}</td><td>${money(l.costo)}</td><td>${money(l.unit)}</td><td>${money(l.unit-l.costo)}</td><td>${money((l.unit-l.costo)*l.q)}</td></tr>`).join(''))}</details><b>Total ${money(quote.total)}</b><button onclick="print()" class="ml-3 p-2 border">Imprimir / PDF</button></div>`;}
      window.erpShowQuote=showQuote;
      window.erpCotizar=e=>{e.preventDefault();const f=e.currentTarget,operationId=f.dataset.operationId;if(f.dataset.submitted==='1'||quotes.some(q=>q.operationId===operationId)){showMessage('Esta cotizaci&oacute;n ya fue registrada. Si necesita otra, env&iacute;e un nuevo documento desde el formulario.');return;}f.dataset.submitted='1';let d=Object.fromEntries(new FormData(f)),lines=[],margen=num(d.margen)/100;if(margen<0||num(d.vigencia)<=0){showMessage('Revise margen y vigencia: el margen debe ser igual o mayor que cero y la vigencia debe ser de al menos un d&iacute;a.');f.dataset.submitted='0';return;}for(let i=1;i<=10;i++){let code=(d['c'+i]||'').trim().toUpperCase(),q=num(d['q'+i]);if(!code&&q===0)continue;if(!code||q<=0){showMessage(`L&iacute;nea ${i}: escriba un c&oacute;digo y una cantidad mayor que cero, o deje ambos campos vac&iacute;os.`);f.dataset.submitted='0';return;}let p=product(code)||designs.find(x=>!x.archived&&String(x.codigo).toUpperCase()===code);if(!p){showMessage(`L&iacute;nea ${i}: el c&oacute;digo ${code} no est&aacute; en Productos terminados ni en No fabricados. Cree o corrija primero el producto y vuelva a cotizar.`);f.dataset.submitted='0';return;}if(!Number.isFinite(Number(p.costo))||num(p.costo)<=0){showMessage(`L&iacute;nea ${i}: ${code} tiene costo pendiente o en cero. Corrija su ficha/costo en el cat&aacute;logo o resuelva la conciliaci&oacute;n antes de cotizar.`);f.dataset.submitted='0';return;}let unit=num(p.costo)*(1+margen);lines.push({code,detalle:p.detalle,q,unit,total:unit*q,costo:num(p.costo)});}if(!lines.length){showMessage('Agregue al menos una l&iacute;nea con c&oacute;digo y cantidad.');f.dataset.submitted='0';return;}const issued=d.fecha||fechaLocal(),quote={id:uid(),operationId,numero:`COT-${Date.now()}`,cliente:(d.cliente||'').trim().replace(/\s+/g,' '),fecha:issued,vence:quoteDue(issued,num(d.vigencia)),total:Math.round(lines.reduce((s,l)=>s+l.total,0)),margen,lines};if(quote.cliente&&!clientes.some(c=>c.toLowerCase()===quote.cliente.toLowerCase()))clientes.push(quote.cliente);quotes.push(quote);save();showQuote(quote);f.reset();f.dataset.submitted='0';f.dataset.operationId=uid();};
      window.erpCotizacionEspecial=e=>{try{const op=e.currentTarget.dataset.operationId;if(quotes.some(q=>q.operationId===op))throw Error('Esta cotizaci&oacute;n ya fue registrada. Si necesita otra, env&iacute;e un nuevo documento desde el formulario.');const d=data(e),code=(d.codigo||'').trim().toUpperCase(),p=product(code)||designs.find(x=>!x.archived&&String(x.codigo).toUpperCase()===code),cfg=config(code),q=num(d.cantidad),w=num(d.ancho),l=num(d.largo),margen=num(d.margen)/100,base=quoteBaseDimensions(code,p),baseArea=base.width*base.length,factor=baseArea>0?w*l/baseArea:0;if(!p||!base.width||!base.length||!Number.isFinite(Number(p.costo))||num(p.costo)<=0)throw Error('Esta modalidad solo admite productos fabricados. Registre primero el producto en la Calculadora de costos y guarde una ficha con costo, ancho y largo base v&aacute;lidos. Los productos de reventa, como palos de madera, se cotizan en Cotizaci&oacute;n general.');requireQty(q);if(w<=0||l<=0||margen<0||num(d.vigencia)<=0)throw Error('Revise las medidas: ancho y largo deben ser mayores que cero; margen no puede ser negativo y la vigencia debe ser de al menos un d&iacute;a.');const costo=num(p.costo)*factor,unit=costo*(1+margen),issued=d.fecha||fechaLocal(),quote={id:uid(),operationId:d._operationId,numero:`COT-${Date.now()}`,cliente:(d.cliente||'').trim().replace(/\s+/g,' '),fecha:issued,vence:quoteDue(issued,num(d.vigencia)),total:Math.round(unit*q),margen,lines:[{code,detalle:p.detalle+` - ${w} x ${l} cm`,q,unit,total:unit*q,costo}],specialMeasure:{baseWidth:base.width,baseLength:base.length,baseSource:base.source,width:w,length:l,factor}};if(quote.cliente&&!clientes.some(c=>c.toLowerCase()===quote.cliente.toLowerCase()))clientes.push(quote.cliente);quotes.push(quote);save();showQuote(quote);e.currentTarget.reset();e.currentTarget.dataset.submitted='0';e.currentTarget.dataset.operationId=uid();pendingOperationForm=null;}catch(err){if(e.currentTarget?.isConnected)e.currentTarget.dataset.submitted='0';pendingOperationForm=null;showMessage(err.message)}};
      window.erpPlan=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.currentTarget)),p=product(d.codigo),cfg=config(d.codigo);if(!p){showMessage('Seleccione producto existente.');return;}let factor=num(d.ancho)*num(d.largo)/(num(cfg.anchoBase||d.ancho)*num(cfg.largoBase||d.largo)),q=num(d.cantidad),rows=[];for(let m of cfg.materiales||[]){let item=mpItem(m.codigo),area=num(m.ancho)*num(m.largo),amount=area?area*factor*num(m.cantidad)*q:num(m.cantidad)*factor*q,invalid=!!item?.unitDimensionsAmbiguous;rows.push({codigo:m.codigo,unidad:item?.unidad||'?',cantidad:amount,ancho:m.ancho,largo:m.largo,costo:item&&!invalid?amount*num(item.precio)/(Math.max(1,num(item.largo)*num(item.ancho))):null,obs:!item?'Falta material en catalogo':invalid?'Unidades/dimensiones por conciliar':''});}let c=mpItem('CIERRE'),closure=.58*2*(num(d.ancho)+num(d.largo))*q;rows.push({codigo:'CIERRE',unidad:c?.unidad||'cm',cantidad:closure,ancho:'-',largo:'-',costo:c?closure*num(c.precio):null,obs:c?'':'Falta costo de cierre'});document.getElementById('planOut').innerHTML=table(['Material','Codigo','Unidad','Cantidad total','Ancho de corte','Largo de corte','Costo estimado','Observaciones'],rows.map(r=>`<tr><td>${esc(mpItem(r.codigo)?.detalle||r.codigo)}</td><td>${esc(r.codigo)}</td><td>${esc(r.unidad)}</td><td>${r.cantidad.toFixed(2)}</td><td>${r.ancho}</td><td>${r.largo}</td><td>${r.costo===null?'Dato faltante':money(r.costo)}</td><td>${esc(r.obs)}</td></tr>`).join(''));};
