        if(role==='thread')return {component:'Hilo',function:'Une las piezas mediante las costuras del producto.'};
        if(role==='closure')return {component:'Cierres',function:'Permite abrir y cerrar la funda para retirar o acceder al relleno.'};
        if(role==='accessory')return {component:'Otros accesorios',function:''};
        if(text.includes('etiqueta'))return {component:'Etiquetas',function:'Identifica la marca o referencia del producto.'};
        if(text.includes('empaque'))return {component:'Empaque',function:'Protege y presenta el producto para almacenamiento o entrega.'};
        if(text.includes('bordo interno'))return {component:'Bordos internos',function:'Forma la pared interna y une las tapas por el lado interior.'};
        if(text.includes('bordo externo'))return {component:'Bordos externos',function:'Forma la pared exterior y remata el perímetro del producto.'};
        if(text.includes('bordo'))return {component:'Bordos',function:'Conforma la pared lateral entre las tapas.'};
