        if(text.includes('forro de espuma')&&text.includes('cara inferior'))return {component:'Forro inferior de espuma',function:'Cubre la cara inferior del núcleo de espuma.'};
        if(text.includes('forro de espuma'))return {component:'Forro de espuma',function:'Cubre los laterales o superficies restantes del núcleo.'};
        if(text.includes('forro interior'))return {component:'Forro adicional',function:'Capa interior adicional de protección o separación.'};
